 @Override public void onCreate(Bundle b){super.onCreate(b);immersive();android.widget.FrameLayout landing=new android.widget.FrameLayout(this);landing.setBackgroundColor(0xff0e151f);setContentView(landing);String saved=getPreferences(0).getString("server","");String mode=getPreferences(0).getString("startup-mode","server");if(getPreferences(0).getBoolean("skip-setup",false)){if(mode.equals("local"))showLocal();else if(!saved.isEmpty())connect(saved);else serverSettings();}else serverSettings();handler.postDelayed(diagnostics,5000);}
