 private String asset(String name)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getAssets().open(name)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}return out.toString("UTF-8");}
