 private void serverSettings(){exitFullscreen();if(setup!=null&&setup.isShowing())return;boolean previous=settings;settings=true;String saved=getPreferences(0).getString("server","");setup=new StartupDialog(this,saved,getPreferences(0).getString("startup-mode","server"),new StartupDialog.Listener(){public void server(String url,boolean remember){getPreferences(0).edit().putString("server",url).putString("startup-mode","server").putBoolean("skip-setup",remember).apply();connect(url);}public void local(boolean remember){getPreferences(0).edit().putString("startup-mode","local").putBoolean("skip-setup",remember).apply();showLocal();}public void cancelled(){settings=previous;if(web==null)finish();}});setup.show();}
